+const ground=432;
+function fighter(x,face,hero){return{x,y:ground,vx:0,vy:0,face,hero,hp:100,attack:'',attackT:0,cool:0,guard:false,stun:0,anim:0,hitDone:false,aiWait:.6}}
+let p=fighter(300,1,true),e=fighter(660,-1,false);
+const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/960,0,0,canvas.height/540,0,0)}
+new ResizeObserver(resize).observe(canvas);resize();
+function rr(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
+function line(x1,y1,x2,y2,color,width=2){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
+function drawBackground(){
+ const g=ctx.createLinearGradient(0,0,0,540);g.addColorStop(0,'#12182a');g.addColorStop(.58,'#30304a');g.addColorStop(1,'#67515a');ctx.fillStyle=g;ctx.fillRect(0,0,960,540);
+ // moon glow
+ const glow=ctx.createRadialGradient(690,122,8,690,122,210);glow.addColorStop(0,'#fff2d6');glow.addColorStop(.16,'#f8deb4aa');glow.addColorStop(1,'#f8deb400');ctx.fillStyle=glow;ctx.fillRect(440,0,500,350);ctx.fillStyle='#f9ebce';ctx.beginPath();ctx.arc(690,122,48,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e6d4bd';ctx.beginPath();ctx.arc(676,112,5,0,Math.PI*2);ctx.arc(706,136,8,0,Math.PI*2);ctx.fill();
+ // far skyline
+ ctx.fillStyle='#171b2c';for(let i=0;i<13;i++){let x=i*82-20,w=52+(i%3)*16,h=65+(i*37%100);ctx.fillRect(x,316-h,w,h);for(let yy=330-h;yy<310;yy+=19)for(let xx=x+8;xx<x+w-5;xx+=14){ctx.fillStyle=(i+xx+yy)%4?'#dca96835':'#92d4d525';ctx.fillRect(xx,yy,5,8)}ctx.fillStyle='#171b2c'}
+ // pagoda silhouette
+ ctx.fillStyle='#121625';ctx.fillRect(80,230,142,100);ctx.beginPath();ctx.moveTo(55,236);ctx.lineTo(151,192);ctx.lineTo(248,236);ctx.lineTo(222,239);ctx.lineTo(151,210);ctx.lineTo(81,239);ctx.closePath();ctx.fill();ctx.fillRect(101,179,98,52);ctx.beginPath();ctx.moveTo(82,183);ctx.lineTo(150,148);ctx.lineTo(218,183);ctx.lineTo(196,185);ctx.lineTo(150,164);ctx.lineTo(104,185);ctx.closePath();ctx.fill();ctx.fillRect(145,129,11,26);ctx.beginPath();ctx.moveTo(139,131);ctx.lineTo(150,112);ctx.lineTo(162,131);ctx.closePath();ctx.fill();
+ // roof beams and floor
+ ctx.fillStyle='#201c2b';ctx.fillRect(0,329,960,30);ctx.fillStyle='#7a4648';ctx.fillRect(0,359,960,12);ctx.fillStyle='#322b3a';ctx.fillRect(0,371,960,169);
+ for(let x=-20;x<1020;x+=88){line(x,372,x+42,540,'#8e687052',2)}for(let y=404;y<540;y+=31)line(0,y,960,y,'#b17f6552',2);
+ // lanterns
+ for(const x of [70,880]){line(x,0,x,155,'#1b1b2b',3);ctx.fillStyle='#3d2531';ctx.fillRect(x-18,148,36,54);ctx.fillStyle='#ffae5d';ctx.fillRect(x-13,154,26,41);const lg=ctx.createRadialGradient(x,174,3,x,174,56);lg.addColorStop(0,'#ffb55488');lg.addColorStop(1,'#ffad4d00');ctx.fillStyle=lg;ctx.fillRect(x-56,120,112,112);line(x-21,147,x+21,147,'#221b25',3);line(x-16,201,x+16,201,'#221b25',3)}
+ // floor glow + platform
+ const fg=ctx.createRadialGradient(480,430,10,480,430,450);fg.addColorStop(0,'#d58a6540');fg.addColorStop(1,'#d58a6500');ctx.fillStyle=fg;ctx.fillRect(0,360,960,180);
+ ctx.fillStyle='#241f2b';ctx.beginPath();ctx.ellipse(480,436,330,38,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#b2835b88';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(480,435,270,23,0,0,Math.PI*2);ctx.stroke();
+ // tiny drifting embers
+ for(let i=0;i<15;i++){let x=(i*173+tick*.24)%960,y=220+((i*71+tick*.12)%255);ctx.fillStyle=i%3?'#ffc07852':'#9ae8df52';ctx.fillRect(x,y,2,2)}
+}
+function drawFighter(f){
+ const x=f.x,y=f.y,dir=f.face,move=Math.abs(f.vx)>8?1:0,bob=Math.sin(f.anim*9)*2*move+(f.y<ground?-3:0),c=f.hero?'#e9ad67':'#73cbd0',dark=f.hero?'#a95f53':'#3e677d',cloth=f.hero?'#f4e3c4':'#d7e8e4';
+ ctx.save();ctx.translate(x,y+bob);ctx.scale(dir,1);
+ // shadow
+ ctx.fillStyle='#090b12aa';ctx.beginPath();ctx.ellipse(0,4,43-(ground-f.y)*.04,9,0,0,Math.PI*2);ctx.fill();
+ let lift=ground-f.y;
+ // legs / stance
+ let stride=Math.sin(f.anim*10)*move*9;line(-6, -47, -15+stride,-12,dark,14);line(-15+stride,-12,-28+stride,-3,'#151c2d',10);line(7,-47,15-stride,-13,dark,14);line(15-stride,-13,28-stride,-3,'#151c2d',10);
+ // gi trousers
+ ctx.fillStyle=dark;ctx.beginPath();ctx.moveTo(-17,-59);ctx.lineTo(17,-59);ctx.lineTo(20,-37);ctx.lineTo(7,-32);ctx.lineTo(0,-47);ctx.lineTo(-8,-32);ctx.lineTo(-23,-38);ctx.closePath();ctx.fill();
+ // torso, athletic gi
+ ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(-17,-114);ctx.quadraticCurveTo(-26,-106,-22,-76);ctx.lineTo(-18,-54);ctx.lineTo(18,-54);ctx.lineTo(22,-79);ctx.quadraticCurveTo(25,-105,16,-114);ctx.closePath();ctx.fill();
+ // chest/gi lapels
+ ctx.fillStyle=cloth;ctx.beginPath();ctx.moveTo(-16,-112);ctx.lineTo(0,-93);ctx.lineTo(12,-113);ctx.lineTo(20,-105);ctx.lineTo(7,-77);ctx.lineTo(-2,-84);ctx.lineTo(-11,-73);ctx.lineTo(-22,-104);ctx.closePath();ctx.fill();
+ ctx.fillStyle=f.hero?'#c4514f':'#323c55';ctx.fillRect(-18,-69,36,7);ctx.beginPath();ctx.moveTo(0,-68);ctx.lineTo(-8,-61);ctx.lineTo(1,-57);ctx.lineTo(7,-62);ctx.closePath();ctx.fill();
+ // head, hair and band
+ ctx.fillStyle='#bf805f';ctx.beginPath();ctx.ellipse(0,-128,15,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=f.hero?'#24202b':'#241d26';ctx.beginPath();ctx.moveTo(-16,-133);ctx.quadraticCurveTo(-20,-155,1,-152);ctx.quadraticCurveTo(19,-151,17,-131);ctx.lineTo(10,-137);ctx.lineTo(-2,-139);ctx.lineTo(-14,-132);ctx.closePath();ctx.fill();
+ if(f.hero){ctx.fillStyle='#e2d2c1';ctx.fillRect(-15,-140,31,5);ctx.fillStyle='#d65250';ctx.beginPath();ctx.moveTo(14,-138);ctx.lineTo(32,-134+Math.sin(tick*.12)*3);ctx.lineTo(19,-129);ctx.closePath();ctx.fill()}
+ ctx.fillStyle='#1b1a23';ctx.beginPath();ctx.arc(7,-129,1.5,0,Math.PI*2);ctx.fill();line(5,-122,10,-121,'#6b3940',1.4);
+ // arms shift by move/guard/strike
+ let reach=0;if(f.attack==='punch'&&f.attackT>.08)reach=31*Math.sin(Math.PI*f.attackT);if(f.attack==='kick'&&f.attackT>.08)reach=10*Math.sin(Math.PI*f.attackT);
+ let guard=f.guard?13:0;
+ line(-14,-105,-26-guard,-83,'#bf805f',11);line(-26-guard,-83,-27-guard,-70,'#bf805f',9);rr(-34-guard,-76,16,12,5,f.hero?'#f1e7d7':'#d8e6e1');
+ line(14,-105,24+reach,-88-(f.attack==='kick'?8:0),'#bf805f',11);line(24+reach,-88-(f.attack==='kick'?8:0),33+reach,-83-(f.attack==='kick'?10:0),'#bf805f',9);rr(27+reach,-89-(f.attack==='kick'?10:0),18,14,6,cloth);
+ if(f.attack==='kick'&&f.attackT>.12&&f.attackT<.78){line(9,-48,42,-42,'#bf805f',13);line(42,-42,70,-39,'#151c2d',11)}
+ // glove wraps
+ ctx.strokeStyle=f.hero?'#fff0d6':'#c8f3ec';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(28+reach,-85);ctx.lineTo(41+reach,-85);ctx.stroke();
