input.newString:
 ctx.restore();
}
function burst(x,y,color){for(let i=0;i<9;i++){let a=Math.random()*Math.PI*2,s=40+Math.random()*180;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-35,t:.35+Math.random()*.35,color})}}
function act(f,type){if(!running||f.stun>0||f.cool>0||f.attackT>0)return;f.attack=type;f.attackT=type==='kick'?.42:.32;f.cool=type==='kick'?.64:.43;f.hitDone=false;}
function strike(a,b,dt){if(!a.attackT||a.hitDone)return;const total=a.attack==='kick'?.42:.32,progress=1-a.attackT/total;if(progress<.23||progress>.72)return;let range=a.attack==='kick'?125:91;let dx=(b.x-a.x)*a.face;if(dx<8||dx>range||Math.abs((b.y-a.y))>90)return;a.hitDone=true;let damage=a.attack==='kick'?13:8;if(b.guard)damage*=.26;b.hp=Math.max(0,b.hp-damage);b.stun=b.guard?.06:.22;b.vx=a.face*(b.guard?55:155);shake=b.guard?2:6;flash=.09;burst((a.x+b.x)/2,b.y-85,a.hero?'#ffcf70':'#77ece2');if(b.hp<=0)finish(a.hero?'AKARI WINS':'ROOK WINS');}
function finish(text){running=false;ended=true;document.getElementById('headline').innerHTML=text==='AKARI WINS'?'You <span>Win!</span>':'Round <span>Lost</span>';document.getElementById('intro').textContent=text==='AKARI WINS'?'A clean finish. The night belongs to Akari. Ready to run it back?':'Rook takes this round, but every fighter gets another chance. Reset your stance and try again.';startButton.textContent='Fight again  →';overlay.classList.remove('hidden');document.getElementById('hint').textContent='Match complete · tap fight again to rematch';}
function update(dt){tick+=dt*60;if(!running)return;clock-=dt;if(clock<=0){clock=0;finish(p.hp>=e.hp?'AKARI WINS':'ROOK WINS')}
 p.anim+=dt;p.cool=Math.max(0,p.cool-dt);p.attackT=Math.max(0,p.attackT-dt);p.stun=Math.max(0,p.stun-dt);p.guard=keys.guard&&p.stun<=0&&!p.attackT;
 let move=(keys.right?1:0)-(keys.left?1:0);if(p.stun<=0&&!p.guard&&p.attackT<=0){p.vx=move*190;if(keys.jump&&p.y>=ground-1)p.vy=-410}else p.vx*=.68;
 if(keys.punch)act(p,'punch');if(keys.kick)act(p,'kick');
 p.x+=p.vx*dt;p.vy+=1080*dt;p.y+=p.vy*dt;if(p.y>=ground){p.y=ground;p.vy=0}p.x=clamp(p.x,75,885);
 e.anim+=dt;e.cool=Math.max(0,e.cool-dt);e.attackT=Math.max(0,e.attackT-dt);e.stun=Math.max(0,e.stun-dt);e.guard=false;e.aiWait-=dt;
 let dist=Math.abs(p.x-e.x),toward=p.x<e.x?-1:1;e.face=toward;p.face=p.x<e.x?1:-1;
 if(e.stun<=0){if(dist>112){e.vx=toward*112;e.guard=false}else{e.vx=0;e.guard=Math.random()<.008;if(e.aiWait<=0&&e.cool<=0){if(Math.random()<.23){e.guard=true;e.aiWait=.38}else{act(e,Math.random()<.62?'punch':'kick');e.aiWait=.55+Math.random()*.45}}}}else e.vx*=.6;
 e.x+=e.vx*dt;e.vy+=1080*dt;e.y+=e.vy*dt;if(e.y>=ground){e.y=ground;e.vy=0}e.x=clamp(e.x,75,885);
 // prevent overlap without locking attacks
 if(Math.abs(e.x-p.x)<42){let push=(42-Math.abs(e.x-p.x))/2;p.x-=p.face*push;e.x+=p.face*push}
 strike(p,e,dt);strike(e,p,dt);
 for(const q of particles){q.t-=dt;q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=220*dt}particles=particles.filter(q=>q.t>0);shake=Math.max(0,shake-dt*20);flash=Math.max(0,flash-dt);
 hp1.style.width=p.hp+'%';hp2.style.width=e.hp+'%';timerEl.textContent=Math.ceil(clock).toString().padStart(2,'0');
}
function draw(){ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawBackground();
 // fighter floor decals
 for(const f of [p,e]){ctx.fillStyle=f.hero?'#ffca7145':'#63ded945';ctx.beginPath();ctx.ellipse(f.x,ground-1,39,7,0,0,Math.PI*2);ctx.fill()}
 drawFighter(e);drawFighter(p);
 for(const q of particles){ctx.globalAlpha=clamp(q.t*2,0,1);ctx.fillStyle=q.color;ctx.beginPath();ctx.arc(q.x,q.y,2+q.t*3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 if(flash>0){ctx.fillStyle=`rgba(255,244,218,${flash*1.6})`;ctx.fillRect(0,0,960,540)}ctx.restore();requestAnimationFrame(frame)}
function frame(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);draw()}
function start(){p=fighter(300,1,true);e=fighter(660,-1,false);clock=60;running=true;ended=false;particles=[];keys.punch=keys.kick=false;hp1.style.width='100%';hp2.style.width='100%';timerEl.textContent='60';document.getElementById('headline').innerHTML='Dojo <span>Duel</span>';document.getElementById('intro').textContent='A fast, focused one-on-one martial arts showdown. Outthink Rook, land clean strikes, and own the final round.';startButton.textContent='Enter the ring  →';document.getElementById('hint').textContent='Move · Strike · Guard · Claim the courtyard';overlay.classList.add('hidden');last=performance.now()}
startButton.addEventListener('click',start);
const map={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowUp:'jump',KeyW:'jump',Space:'jump',KeyJ:'punch',KeyK:'kick',KeyL:'guard'};
window.addEventListener('keydown',ev=>{let k=map[ev.code];if(!k)return;ev.preventDefault();if(!keys[k]){keys[k]=true;if(k==='punch')act(p,'punch');if(k==='kick')act(p,'kick')} });
window.addEventListener('keyup',ev=>{let k=map[ev.code];if(k)keys[k]=false});window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
document.querySelectorAll('.control').forEach(button=>{const key=button.dataset.key;const down=ev=>{ev.preventDefault();button.classList.add('pressed');if(key==='punch')act(p,'punch');else if(key==='kick')act(p,'kick');else if(key==='jump'&&p.y>=ground-1)p.vy=-410;else if(key==='left'||key==='right'||key==='guard')keys[key]=true};const up=ev=>{ev.preventDefault();button.classList.remove('pressed');if(key==='left'||key==='right'||key==='guard')keys[key]=false};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('pointerleave',up)});
requestAnimationFrame(frame);
})();
</script>
</body>
</html>

